      cctv: [
        { id: 'A.c1', type: 'enOpts', prompt: '-아/어/여도 means…', opts: ['even if; even though', 'so; because', 'and then', 'before -ing'], skill: 'l20.usage', explain: 'Textbook: -아/어/여도 = even if, even though.', en: '' },
        { id: 'A.c2', type: 'mc', prompt: '울다 (to cry) → “even if you cry”', opts: ['울어도', '울아도', '우러도', '울도'], skill: 'l20.form', explain: 'Textbook: 울다 → 울어도.', en: '' },
        { id: 'A.c3', type: 'enOpts', prompt: '“택시를 타도, 시간이 오래 걸려요.”', opts: ['It takes a long time even if I take a taxi.', 'I take a taxi because it takes a long time.', 'If I take a taxi, it is fast.', 'I rode a taxi for a long time.'], skill: 'l20.usage', explain: 'Textbook sample sentence.', en: 'It takes a long time even if I take a taxi.' },
        { id: 'A.c4', type: 'mc', prompt: '공부하다 → “even if you study”', opts: ['공부해도', '공부하도', '공부하아도', '공부해서'], skill: 'l20.form', explain: 'Textbook: 공부해도 (= 공부하여도).', en: '' },
        { id: 'A.c5', type: 'enOpts', prompt: '-아/어/여도 has the same meaning as which word from Lesson 12?', opts: ['그래도', '그래서', '그리고', '그럼'], skill: 'l20.usage', explain: 'Textbook: the same meaning as 그래도, but it combines two sentences into one.', en: '' },
        { id: 'A.c6', type: 'enOpts', prompt: '“냄새는 이상해도 맛있어요.”', opts: ['It is tasty even though it smells weird.', 'It smells weird, so it is not tasty.', 'It smells good and tastes good.', 'It is weird that it is tasty.'], skill: 'l20.usage', explain: 'Textbook sample sentence.', en: 'It is tasty even though it smells weird.' },
      ],
