          q: { type: 'write', prompt: 'Answer: “Even though it’s difficult, it’s fun.”', ans: ['어려워도 재미있어요.'], soft: [{ p: '(네 |조금 |좀 |)어려워도 재미있어요', note: 'Accepted.' }, { p: '(조금 |좀 |)어려워도 재미있었어요', note: 'Accepted (past: it was fun).' }], skill: 'l20.irr',
            diag: [{ p: '(어렵어도|어려와도|어렵아도) 재미있어요', note: '어렵다 is ㅂ-irregular: 어려워요 → 어려워도.' }, { p: '어려워서 재미있어요', note: '어려워서 = it’s difficult, SO it’s fun. Even though = 어려워도.' }],
            explain: '어렵다 → 어려워요 → 어려워도.', en: 'Even though it’s difficult, it’s fun.' },
          after: [['boss', '하하. 힘들어도 재미있어요? 좋아요!', 'Ha ha. It’s hard but fun? Great!']],
